func (valSet *defaultSet) QuorumSize() int {
	//c.currentLogger(true, nil).Trace("WBFT: confirmation Formula used ceil(2N/3)")
	return int(math.Ceil(float64(valSet.Size()) - valSet.F()))
}

ValidatorSet interface {
	// Calculate the proposer
	CalcProposer(lastProposer common.Address, round uint64)
	// Return the validator size
	Size() int
	// Return the validator array
	List() []Validator
	// Return the validator address array
	AddressList() []common.Address
	// Get validator by index
	GetByIndex(i uint64) Validator
	// Get validator by given address
	GetByAddress(addr common.Address) (int, Validator)
	// Get current proposer
	GetProposer() Validator
	// Check whether the validator with given address is a proposer
	IsProposer(address common.Address) bool
	// Add validator
	AddValidator(address common.Address, blsPublicKey []byte) bool
	// Remove validator
	RemoveValidator(address common.Address) bool
	// Copy validator set
	Copy() ValidatorSet
	// Get the maximum number of faulty nodes
	F() float64
	// Get quorum size ( which is n-f)
	QuorumSize() int
	// Get proposer policy
	Policy() ProposerPolicy
}

